record.field:
activity_type_ids = env['ir.model.data'].search([
    ('module', '=', 'fmcg_business_automation'),
    ('model', '=', 'mail.activity.type'),
]).mapped('res_id')

pickings = env['stock.picking'].search([
    ('state', 'not in', ['done', 'cancel']),
], limit=50, order='create_date asc, id asc')

for picking in pickings:
    activity = env['mail.activity'].search([
        ('res_model', '=', 'stock.picking'),
        ('res_id', '=', picking.id),
        ('activity_type_id', 'in', activity_type_ids),
    ], order='create_date desc, id desc', limit=1)

    if not activity:
        if picking.state == 'draft':
            confirm_draft_type = env.ref(
                'fmcg_business_automation.mail_activity_type_confirm_draft_picking'
            )
            picking.activity_schedule(
                activity_type_id=confirm_draft_type.id,
                summary='Confirm draft stock picking',
                user_id=env.user.id,
            )
            continue
        elif picking.state == 'assigned':
            validate_type = env.ref(
                'fmcg_business_automation.mail_activity_type_validate_assigned_picking'
            )
            picking.activity_schedule(
                activity_type_id=validate_type.id,
                summary='Validate assigned stock picking',
                user_id=env.user.id,
            )
            continue
        raise UserError(
            'Picking %s (state: %s) chưa hoàn tất nhưng không có Activity để xử lý.'
            % (picking.name, picking.state)
        )

    activity.action_feedback()
